    @Column(name = "balance_date") LocalDate balanceDate
) implements Serializable {
    // Record auto-generates:
    // - equals: both accountId AND balanceDate must match
    // - hashCode: based on both fields
    // - implements Serializable (explicitly declared for JPA requirement)
    // ZERO boilerplate! Perfect composite key class.
}
