package com.bank.balance.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "daily_balances")
public class DailyBalance {

    @EmbeddedId
    private DailyBalanceId id;  // composite key as ONE field

    private BigDecimal balance;

    @Column(name = "day_change")
    private BigDecimal dayChange;

    protected DailyBalance() {}

    public DailyBalance(DailyBalanceId id, BigDecimal balance, BigDecimal dayChange) {
        this.id = id;
        this.balance = balance;
        this.dayChange = dayChange;
    }

    public DailyBalanceId getId() { return id; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getDayChange() { return dayChange; }
}
