// ─── File: src/main/java/com/bank/balance/service/DailyBalanceService.java ───
package com.bank.balance.service;

import com.bank.balance.dto.BalanceResponse;
import com.bank.balance.dto.BalanceResponse.DayBalance;
import com.bank.balance.model.*;
import com.bank.balance.repository.DailyBalanceRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class DailyBalanceService {

    private final DailyBalanceRepository balanceRepo;

    @Transactional(readOnly = true)
    public BalanceResponse getBalanceHistory(String accountId, LocalDate from, LocalDate to) {
        List<DailyBalance> balances = balanceRepo.findByIdAccountIdAndIdBalanceDateBetween(
            accountId, from, to);

        List<DayBalance> days = balances.stream()
            .map(b -> new DayBalance(b.getId().balanceDate().toString(),
                b.getBalance(), b.getDayChange()))
            .toList();

        BigDecimal totalChange = balances.stream()
            .map(DailyBalance::getDayChange)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new BalanceResponse(accountId, days, totalChange);
    }

    @Transactional
    public DailyBalance recordBalance(String accountId, LocalDate date,
                                      BigDecimal balance, BigDecimal change) {
        // Create composite key:
        DailyBalanceId key = new DailyBalanceId(accountId, date);

        // Check if already exists:
        if (balanceRepo.existsById(key)) {
            log.warn("Balance already recorded for {} on {}", accountId, date);
            return balanceRepo.findById(key).orElseThrow();
        }

        DailyBalance record = new DailyBalance(key, balance, change);
        return balanceRepo.save(record);
    }

    @Transactional(readOnly = true)
    public Optional<DailyBalance> findByKey(String accountId, LocalDate date) {
        // Lookup by composite key:
        DailyBalanceId key = new DailyBalanceId(accountId, date);
        return balanceRepo.findById(key);
        // SQL: SELECT ... WHERE account_id = ? AND balance_date = ?
    }
}
```

