// ─── File: src/test/java/com/bank/balance/service/CompositeKeyTest.java ───
package com.bank.balance.service;

import com.bank.balance.model.DailyBalanceId;
import org.junit.jupiter.api.Test;
import java.time.LocalDate;
import static org.assertj.core.api.Assertions.*;

class CompositeKeyTest {

    @Test
    void recordKeyAutoGeneratesEquals() {
        DailyBalanceId key1 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        DailyBalanceId key2 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        assertThat(key1).isEqualTo(key2);  // record equals: both fields match ✅
    }

    @Test
    void recordKeyDiffersWhenFieldsDiffer() {
        DailyBalanceId key1 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        DailyBalanceId key2 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 16));
        assertThat(key1).isNotEqualTo(key2);  // different date → not equal
    }

    @Test
    void recordKeyHashCodeConsistent() {
        DailyBalanceId key1 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        DailyBalanceId key2 = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        assertThat(key1.hashCode()).isEqualTo(key2.hashCode());
    }

    @Test
    void keyIsSerializable() {
        assertThat(java.io.Serializable.class.isAssignableFrom(DailyBalanceId.class)).isTrue();
    }

    @Test
    void accessKeyFieldsViaRecord() {
        DailyBalanceId key = new DailyBalanceId("SAV2001", LocalDate.of(2024, 1, 15));
        assertThat(key.accountId()).isEqualTo("SAV2001");
        assertThat(key.balanceDate()).isEqualTo(LocalDate.of(2024, 1, 15));
    }
}
